DeviceProperties.ListenerScriptPacketParser:
IF(plugTopic = "shellypstripg4-123456789012")
    ADDERROR("Set correct 'plugTopic' value in module variables. It is the MQTT prefix from 'http://shellyIpAddress' -> Settings -> Connectivity -> MQTT, by default 'shellypstripg4-<deviceid>'.");
    RETURN(-1);
END

# Every topic is compared against the full prefix of this device, so the root
# topic may safely be widened (e.g. to shellies/#) to cover several devices.

# Device availability (MQTT last will). A reconnect invalidates the values that
# were read so far, so a fresh status snapshot is requested afterwards.
IF(RECEIVEDMSG.TOPIC = plugTopic + "/online")
    isOnline := IF(TOSTRING(RECEIVEDMSG.PAYLOAD) = "true", 1, 0);
    IF(isOnline = 1, gotStatus := 0);
END

# Reply to the Shelly.GetStatus request sent from the module read script
IF(RECEIVEDMSG.TOPIC = plugTopic + "/taphome/rpc")
    gotStatus := 1;
    VAR rt := PARSEJSON(RECEIVEDMSG.PAYLOAD, "result['switch:0'].temperature.tC", TRUE);
    IF(!ISNULL(rt), internalTemp := rt);
END

# All four sockets report the same internal device temperature, socket 1 is used.
IF(RECEIVEDMSG.TOPIC = plugTopic + "/status/switch:0")
    internalTemp := PARSEJSON(RECEIVEDMSG.PAYLOAD, "temperature.tC");

    VAR errors := PARSEJSON(RECEIVEDMSG.PAYLOAD, "errors", TRUE);
    IF (!ISNULL(errors))
        VAR errCount := LENGTH(errors);
        VAR i := 0;
        VAR errorText := "";

        WHILE i < errCount
            IF LENGTH(errorText)
                errorText += ", ";
            END
            errorText := errorText + GETAT(errors, i);
            i += 1;
        LOOP

        IF LENGTH(errorText)
            ADDERROR(errorText);
        END
    END
END

IF(RECEIVEDMSG.TOPIC = plugTopic + "/events/rpc")
    VAR t := PARSEJSON(RECEIVEDMSG.PAYLOAD, "params['switch:0'].temperature.tC", TRUE);
    IF(!ISNULL(t), internalTemp := t);
END

IF(RECEIVEDMSG.TOPIC = plugTopic + "/status/switch:0")
    St := IF(PARSEJSON(RECEIVEDMSG.PAYLOAD, "output"), 1, 0);
END

IF(RECEIVEDMSG.TOPIC = plugTopic + "/events/rpc")
    VAR output := PARSEJSON(RECEIVEDMSG.PAYLOAD, "params['switch:0'].output", TRUE);
    IF(!ISNULL(output), St := IF(output, 1, 0));
END

# Initial state from the Shelly.GetStatus reply requested by the module
IF(RECEIVEDMSG.TOPIC = plugTopic + "/taphome/rpc")
    VAR initial := PARSEJSON(RECEIVEDMSG.PAYLOAD, "result['switch:0'].output", TRUE);
    IF(!ISNULL(initial), St := IF(initial, 1, 0));
END

DeviceProperties.WriteSwitchStateScriptPacketParser:
# RPC over MQTT - enabled by default on Gen4 devices
VAR rpc := "{\"id\":1,\"src\":\"taphome\",\"method\":\"Switch.Set\",\"params\":{\"id\":0,\"on\":" + IF(St = 1, "true", "false") + "}}";
MQTTPUBLISH(plugTopic + "/rpc", rpc);

# Alternative, only works when Settings -> MQTT -> "Enable MQTT Control" is ticked:
# MQTTPUBLISH(plugTopic + "/command/switch:0", IF(St = 1, "on", "off"));

