DeviceProperties.ListenerScriptPacketParser:
IF(RECEIVEDMSG.TOPIC = plugTopic + "/status/switch:0")
    Ed := PARSEJSON(RECEIVEDMSG.PAYLOAD, "apower") / 1000.0;
    To := PARSEJSON(RECEIVEDMSG.PAYLOAD, "aenergy.total") / 1000.0;
    voltage := PARSEJSON(RECEIVEDMSG.PAYLOAD, "voltage");
    current := PARSEJSON(RECEIVEDMSG.PAYLOAD, "current");
END

IF(RECEIVEDMSG.TOPIC = plugTopic + "/events/rpc")
    VAR apower := PARSEJSON(RECEIVEDMSG.PAYLOAD, "params['switch:0'].apower", TRUE);
    IF(!ISNULL(apower), Ed := apower / 1000.0);
    VAR total := PARSEJSON(RECEIVEDMSG.PAYLOAD, "params['switch:0'].aenergy.total", TRUE);
    IF(!ISNULL(total), To := total / 1000.0);
    VAR v := PARSEJSON(RECEIVEDMSG.PAYLOAD, "params['switch:0'].voltage", TRUE);
    IF(!ISNULL(v), voltage := v);
    VAR a := PARSEJSON(RECEIVEDMSG.PAYLOAD, "params['switch:0'].current", TRUE);
    IF(!ISNULL(a), current := a);
END

# Initial values from the Shelly.GetStatus reply requested by the module
IF(RECEIVEDMSG.TOPIC = plugTopic + "/taphome/rpc")
    VAR iPower := PARSEJSON(RECEIVEDMSG.PAYLOAD, "result['switch:0'].apower", TRUE);
